# ===============================================================================
# RecupIndurex - Raccourci d'acces (poste client)
#
# A copier sur n'importe quel PC du reseau qui doit acceder a l'application
# (PAS le serveur lui-meme - voir install.bat pour le serveur). Cree un
# raccourci sur le Bureau, avec l'icone, pointant vers l'adresse du serveur.
# Aucun autre fichier necessaire - tout est integre dans ce script.
#
# Usage : double-cliquer sur install-raccourci.bat
# ===============================================================================
param(
    [string]$ServerUrl = "http://192.168.100.20/"
)

Set-Location -Path $PSScriptRoot

Write-Host "========================================" -ForegroundColor Yellow
Write-Host " RecupIndurex - Raccourci d'acces" -ForegroundColor Yellow
Write-Host "========================================" -ForegroundColor Yellow

# --- 1. Ecrire l'icone (integree dans ce script, encodee en base64) --------------
$iconDir  = Join-Path $env:LOCALAPPDATA "RecupIndurex"
$iconPath = Join-Path $iconDir "RecupIndurex.ico"
if (-not (Test-Path $iconDir)) { New-Item -ItemType Directory -Path $iconDir -Force | Out-Null }

$iconBase64 = ""
[System.IO.File]::WriteAllBytes($iconPath, [Convert]::FromBase64String($iconBase64))
Write-Host "    OK : Icone preparee"

# --- 2. Creer le raccourci sur le Bureau ------------------------------------------
$shortcutContent = "[InternetShortcut]`r`nURL=$ServerUrl`r`nIconFile=$iconPath`r`nIconIndex=0`r`n"
$desktop = [Environment]::GetFolderPath("Desktop")
$shortcutPath = Join-Path $desktop "RecupIndurex.url"
Set-Content -Path $shortcutPath -Value $shortcutContent -Encoding ASCII -Force

Write-Host "    OK : Raccourci 'RecupIndurex' ajoute sur le Bureau" -ForegroundColor Green
Write-Host ""
Write-Host "Il pointe vers : $ServerUrl"
Write-Host "Pour changer l'adresse plus tard, relancez avec :"
Write-Host '  .\install-raccourci.ps1 -ServerUrl "http://NOUVELLE-IP/"'
Write-Host ""
Write-Host "Appuyez sur une touche pour fermer..."
[System.Console]::ReadKey($true) | Out-Null
